css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .58); position: relative; }
.loader::after { content: ''; position: absolute; left: 0; right: 0; bottom: 6%; height: 2px; background: color-mix(in srgb, var(--accent) 30%, transparent); }
.loader span { position: absolute; left: 0; bottom: 8%; width: calc(var(--loader-size) * .5); height: calc(var(--loader-size) * .5); border-radius: 50%; border: calc(var(--loader-size) * .05) solid var(--accent); box-sizing: border-box; animation: roll calc(var(--loader-speed) * 2) linear infinite; }
.loader span::before, .loader span::after { content: ''; position: absolute; inset: 28% 46%; background: var(--accent-2); border-radius: 2px; }
.loader span::after { transform: rotate(90deg); }
@keyframes roll { 0% { transform: translateX(0) rotate(0deg); } 100% { transform: translateX(calc(var(--loader-size) * .5)) rotate(360deg); } }
